async function render(page){root.classList.remove("page-enter");root.innerHTML='<div class="loading">Loading '+esc(PAGE_NAMES[page])+'…</div>';try{const views={home,browser,games,tools:toolkit,ai,changelog,feedback,settings};root.innerHTML=await views[page]();requestAnimationFrame(()=>root.classList.add("page-enter"));bind(page);revealCards()}catch(e){root.innerHTML=header(PAGE_NAMES[page],"Something went wrong.")+'<div class="empty-state">'+esc(e.message)+'</div>'}}
function navigate(){
 const raw=location.hash.slice(1)||"home",key=raw.startsWith("play?")?"play":raw.startsWith("browser?")?"browser":(PAGE_NAMES[raw]?raw:"home");
 document.querySelectorAll(".rail-link").forEach(a=>a.classList.toggle("active",a.dataset.page===key));
 document.querySelector(".rail-home").classList.toggle("active",key==="home");
 const params=new URLSearchParams(raw.includes("?")?raw.slice(raw.indexOf("?")+1):"");
 const input=document.querySelector("#global-address"),prefix=document.querySelector("#address-prefix"),lock=document.querySelector(".address-lock");
 if(prefix)prefix.textContent=key==="browser"&&params.get("url")?"":"polaris://"+(key==="play"?"games":key);
 if(lock)lock.textContent=key==="browser"&&params.get("url")?"●":"◆";
 if(key==="browser"&&params.get("url")){const url=params.get("url");let tab=state.tabs.find(t=>t.url===url);if(!tab){tab={id:crypto.randomUUID(),title:hostFromUrl(url),url,frameObj:null,loaded:false};state.tabs.push(tab)}state.activeTabId=tab.id;if(input)input.value=browserSettings.showFullUrls?url:hostFromUrl(url)}else{if(input)input.value="";const tab=activeTab();if(tab){tab.title=key==="play"?(params.get("name")||"Game"):PAGE_NAMES[key]||"Home";tab.url="";tab.frameObj=null;tab.loaded=false}}
 document.querySelector("#sidebar").classList.remove("open");renderBrowserTabs();
 if(key==="play")renderGameViewer(params.get("url")||"",params.get("name")||"Game");
 else if(key==="browser"&&params.get("url"))renderBrowser(params.get("url"));else render(key);
}
